function openModalV2(plan) {
  hideListenOverlayV2();
  elsV2.modalCard.classList.add("workspace-mode");
  elsV2.modalAgentIcon.src = plan.agent.icon;
  elsV2.modalAgentIcon.alt = plan.agent.name;
  elsV2.modalTitle.textContent = plan.agent.name;
  elsV2.modalSubtitle.textContent = `${plan.agent.subtitle} · ${plan.targetPage}`;
  elsV2.modalTools.innerHTML = renderModalToolsV2(plan.toggles);
  elsV2.modalBody.innerHTML = plan.action === "answer_direct" ? renderAnswerViewV2(plan) : renderWorkspaceV2(plan);
  elsV2.modalLayer.classList.add("active");
  elsV2.modalLayer.setAttribute("aria-hidden", "false");
  bindModalV2(plan);
  stateV2.modalVoiceLoop = true;
  window.setTimeout(() => autoRelistenModalV2(), 2200);
}

function closeModalV2() {
  if (elsV2.modalLayer.contains(document.activeElement)) {
    document.activeElement.blur();
  }
  elsV2.modalLayer.classList.remove("active");
  elsV2.modalLayer.setAttribute("aria-hidden", "true");
  elsV2.modalCard.classList.remove("workspace-mode");
  clearScriptTimersV2();
  stateV2.pendingModalPlan = null;
  stateV2.currentPlan = null;
  stateV2.modalVoiceLoop = false;
  scheduleAmbientV2();
}

function streamIntoElement(targetEl, text, options) {
  var speed = (options && options.speed) || 22;
  var onDone = (options && options.onDone) || function() {};
  var index = 0;
  targetEl.textContent = "";
  var tick = function() {
    index += Math.max(1, text[index] === " " ? 2 : 1);
    targetEl.textContent = text.slice(0, index);
    if (index < text.length) {
      window.setTimeout(tick, speed);
    } else {
      onDone();
    }
  };
  window.setTimeout(tick, 30);
}

function appendUserTurnV2(userText) {
  var thread = document.getElementById("dialog-thread-v2");
  if (!thread) return;
  thread.insertAdjacentHTML("beforeend",
    '<div class="chat-bubble user">' + escapeHtmlV2(userText) + '</div>');
  thread.scrollTop = thread.scrollHeight;
}

function appendAiTurnStreamingV2(replyText, onDoneExtra) {
  var thread = document.getElementById("dialog-thread-v2");
  if (!thread) return;
  var thinkingId = "thinking-" + Date.now();
  thread.insertAdjacentHTML("beforeend",
    '<div class="chat-bubble ai thinking" id="' + thinkingId + '">' +
    '<span class="thinking-dots"><i></i><i></i><i></i></span></div>');
  thread.scrollTop = thread.scrollHeight;
  var delay = 500 + Math.floor(Math.random() * 500);
  window.setTimeout(function() {
    var el = document.getElementById(thinkingId);
    if (!el) return;
    el.classList.remove("thinking");
    el.innerHTML = "";
    streamIntoElement(el, replyText, {
      speed: 22,
      onDone: function() {
        thread.scrollTop = thread.scrollHeight;
        if (onDoneExtra) onDoneExtra();
        if (stateV2.modalVoiceLoop) {
          window.setTimeout(function() { autoRelistenModalV2(); }, 900);
        }
      }
    });
  }, delay);
}

function appendDialogV2(userText, replyText) {
  appendUserTurnV2(userText);
  appendAiTurnStreamingV2(replyText);
}

function followReplyV2(plan, text) {
  const value = normalizeV2(text);
  if (plan.metric) {
    if (value.includes("差异") || value.includes("原因")) return "差异主要来自两方面：一是回款提前到账，二是成本管控到位，整体超计划 2.1%。";
    if (value.includes("趋势") || value.includes("走势")) return "从趋势看，4 月低点后持续回升，5 到 6 月涨势最明显，与营收节奏吻合。";
    if (value.includes("上个月") || value.includes("环比") || value.includes("对比")) return "环比上月提升 3.4 个百分点，主要因为本月回款集中到账，成本端也有所压降。";
    return "指标页已经打开，你可以继续问差异原因、趋势走势或环比对比。";
  }
  if (plan.agent.id === "agent-xingguan") {
    if (value.includes("改到") || value.includes("调整") || value.includes("换到")) return "可以，会议时间已建议调整，你可以继续改会议室或主题，改好后直接提交。";
    if (value.includes("主题")) return "收到，新主题已写入预约表单，主题填好后点提交就能完成预约。";
    return "会议预约任务已继续承接，你可以继续改时间、补主题或直接提交预约。";
  }
  if (plan.agent.id === "agent-zonghe") {
    if (value.includes("联系人") || value.includes("是谁")) return "当前责任部门是综合管理部人事岗，联系人为王晓宁，可以直接电话或 OA 联系。";
    if (value.includes("流程") || value.includes("几步") || value.includes("步骤")) return "审批流程共 3 步：OA 发起申请 → 部门负责人审批 → 综合管理部备案，通常 2 个工作日内完成。";
    if (value.includes("3天") || value.includes("三天") || value.includes("以上") || value.includes("长假")) return "连续 3 天及以上假期需在 OA 备注说明事由，并附上部门负责人知情确认，综合管理部备案时间不变。";
    return "制度问答已继续展开，你可以继续问流程步骤、联系人或 3 天以上假期要求。";
  }
  if (plan.agent.id === "agent-keshu") {
    if (value.includes("建议")) return "下一步建议优先关注工程域成本压降，其次复核生产域设备瓶颈。";
    if (value.includes("环比")) return "从环比看，开发域增长最快，工程域恢复最明显。";
    return "分析链路已继续展开，你可以继续问趋势、建议或汇报口径。";
  }
  if (plan.agent.id === "agent-dangan") {
    if (value.includes("西区") || value.includes("巡检") || value.includes("归档")) return "西区 6 月巡检记录已自动填入档案目录和保管期限，点确认即可完成归档。";
    if (value.includes("长期") || value.includes("保管期限") || value.includes("期限")) return "保管期限已改为长期保管，适用于涉及关键合同或重要项目的档案资料。";
    if (value.includes("确认") || value.includes("提交")) return "档案归档已准备就绪，点击确认归档按钮即可完成归档，系统会自动生成归档编号。";
    return "档案归档页已承接你的追问，你可以继续改目录、期限或直接确认提交。";
  }
  if (plan.agent.id === "agent-hetong") {
    if (value.includes("待确认") || value.includes("确认项")) return "当前待确认项主要集中在交底范围、附件完整性和审批前检查三部分，全部确认后可提交。";
    if (value.includes("摘要") || value.includes("摘要")) return "交底摘要可以自动生成，主要包含合同主体、交底范围和关键日期，生成后你可以再修改。";
    if (value.includes("提交")) return "合同交底表已填写完整，点提交确认后系统会通知相关审批人进行确认。";
    return "合同交底页已承接你的追问，你可以继续看待确认项、补充摘要或直接提交确认。";
  }
  return `${plan.agent.name} 已继续承接你的追问，当前建议沿着"${plan.agent.prompt}"这条任务继续展开。`;
}

function handleFollowV2(plan, text) {
  const reply = followReplyV2(plan, text);
  appendUserTurnV2(text);
  setStateV2("thinking");
  appendAiTurnStreamingV2(reply, function() {
    window.setTimeout(function() { appendFollowSuggestionsV2(plan, text); }, 100);
  });
  toastV2(`已继续在 ${plan.agent.name} 中处理追问`, "success", plan.agent.name);
}

