function buildFollowSuggestionsV2(plan, lastText) {
  const v = normalizeV2(lastText);
  const chips = [];
  if (plan.agent.id === "agent-zonghe") {
    if (v.includes("联系人") || v.includes("是谁")) {
      chips.push("审批流程分几步", "需要什么材料");
    } else if (v.includes("流程") || v.includes("步骤")) {
      chips.push("联系人是谁", "需要什么材料");
    } else if (v.includes("材料") || v.includes("说明")) {
      chips.push("联系人是谁", "审批流程分几步");
    } else {
      chips.push("联系人是谁", "审批流程分几步");
    }
    chips.push("展开到制度工作台");
  } else if (plan.metric || plan.agent.id === "agent-jicai") {
    if (v.includes("差异") || v.includes("原因")) {
      chips.push("趋势走势怎么样", "和上个月比怎么样");
    } else if (v.includes("趋势") || v.includes("走势")) {
      chips.push("差异原因是什么", "和上个月比怎么样");
    } else {
      chips.push("差异原因是什么", "趋势走势怎么样");
    }
    chips.push("展开到指标工作台");
  } else if (plan.agent.id === "agent-dangan") {
    chips.push("保管期限改为长期", "确认提交归档");
  } else if (plan.agent.id === "agent-hetong") {
    chips.push("生成交底摘要", "直接提交确认");
  } else {
    chips.push(...(plan.followups || []).slice(0, 2));
    chips.push("展开到工作台");
  }
  return chips.slice(0, 3);
}

function appendFollowSuggestionsV2(plan, lastText) {
  const thread = document.getElementById("dialog-thread-v2");
  if (!thread) return;
  const chips = buildFollowSuggestionsV2(plan, lastText);
  if (!chips.length) return;
  const html = `<div class="inline-follow-chips">${
    chips.map(c => `<button class="inline-follow-chip" data-prompt="${escapeHtmlV2(c)}">${escapeHtmlV2(c)}</button>`).join("")
  }</div>`;
  thread.insertAdjacentHTML("beforeend", html);
  thread.querySelectorAll(".inline-follow-chip:not([data-bound])").forEach(btn => {
    btn.dataset.bound = "1";
    btn.addEventListener("click", () => {
      const prompt = btn.dataset.prompt;
      if (prompt === "展开到制度工作台" || prompt === "展开到指标工作台" || prompt === "展开到工作台") {
        openModalV2({ ...plan, action: "open_workspace", scriptId: null });
        return;
      }
      handleFollowV2(plan, prompt);
    });
  });
  thread.scrollTop = thread.scrollHeight;
}

function startModalVoiceV2(plan, inputEl) {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) { toastV2("当前浏览器不支持语音识别", "warning", "语音追问"); return; }
  const micBtn = document.getElementById("modal-follow-mic-v2");
  if (micBtn) micBtn.classList.add("listening");
  const rec = new SR();
  rec.lang = "zh-CN";
  rec.continuous = false;
  rec.interimResults = true;
  rec.onresult = (e) => {
    let text = "";
    for (let i = 0; i < e.results.length; i++) text += e.results[i][0].transcript;
    if (inputEl) inputEl.value = text;
  };
  rec.onend = () => {
    if (micBtn) micBtn.classList.remove("listening");
    const value = inputEl ? inputEl.value.trim() : "";
    if (value) {
      handleFollowV2(plan, value);
      if (inputEl) inputEl.value = "";
    } else if (stateV2.modalVoiceLoop) {
      window.setTimeout(function() { autoRelistenModalV2(); }, 1500);
    }
  };
  rec.onerror = () => {
    if (micBtn) micBtn.classList.remove("listening");
  };
  try { rec.start(); } catch (_) {}
}

function autoRelistenModalV2() {
  if (!stateV2.modalVoiceLoop || !stateV2.currentPlan) return;
  if (!elsV2.modalLayer.classList.contains("active")) return;
  const followInput = document.getElementById("modal-follow-input-v2");
  if (followInput) startModalVoiceV2(stateV2.currentPlan, followInput);
}

function fillMockTargetV2(selector, value) {
  const target = document.querySelector(selector);
  if (!target) return;
  if ("value" in target) {
    target.value = value;
  } else {
    target.textContent = value;
  }
  target.classList.add("demo-filled", "demo-pulse-target");
}

function highlightTargetV2(selector, className = "demo-focus-target") {
  const target = document.querySelector(selector);
  if (!target) return;
  target.classList.add(className);
  if (className !== "demo-pulse-target") {
    window.setTimeout(() => target.classList.remove(className), 1400);
  }
}

function advanceStepV2(selector) {
  const target = document.querySelector(selector);
  if (!target) return;
  target.classList.add("demo-step-active");
}

function runDemoStepV2(step, plan) {
  if (!step) return;
  if (step.type === "say") {
    speakV2(step.text);
    return;
  }
  if (step.type === "highlight") {
    highlightTargetV2(step.selector);
    return;
  }
  if (step.type === "pulseTarget") {
    highlightTargetV2(step.selector, "demo-pulse-target");
    return;
  }
  if (step.type === "fillMock") {
    fillMockTargetV2(step.selector, step.value);
    return;
  }
  if (step.type === "advanceStep") {
    advanceStepV2(step.selector);
    return;
  }
  if (step.type === "openModal") {
    if (stateV2.pendingModalPlan) {
      const pendingPlan = stateV2.pendingModalPlan;
      stateV2.pendingModalPlan = null;
      openModalV2(pendingPlan);
    }
  }
}

