  stateV2.currentPlan = plan;
  stateV2.currentAgentId = plan.agent.id;
  stateV2.activeScenarioId = plan.route?.id || "";
  stateV2.directAnswerMode = false;
  stateV2.pendingEntityPrompt = "";
  stateV2.currentFollowupSet = [...(plan.followups || [])];
  stateV2.autoActionQueue = (plan.scenario?.scriptSteps || []).map((step) => step.type);
  hideListenOverlayV2();
  elsV2.mainInput.value = plan.text;
  applyToolStateV2(plan.toggles || []);
  highlightAgentV2(plan.agent.id);
  pointToAgentV2(plan.agent.id);
  showBubbleV2({
    title: `${plan.agent.name} 已承接`,
    copy: bubbleCopy,
    quickItems: buildQuickListV2(plan.followups, DEMO_COMMANDS_V2.filter((item) => item.phrase !== plan.text)),
    sticky: false
  });
}

function executeWorkspaceV2(plan) {
  if (!plan || !plan.agent || stateV2.isExecuting) return;
  stateV2.isExecuting = true;
  clearScriptTimersV2();
  executeVisualV2(plan, `我已直接为你打开 ${plan.targetPage}，可以继续追问或直接操作。`);
  setPetStatusV2(stateV2.standbyEnabled ? "这一页已经打开，你也可以继续直接说下一条命令" : "工作台已经打开，你可以继续追问或直接操作");
  speakV2(plan.scenario?.speechReply || (plan.metric ? `${plan.entities.period}的${plan.metric.label}已经帮你直接打开。` : `已为你打开${plan.agent.name}`));
  window.setTimeout(() => {
    openModalV2(plan);
    stateV2.isExecuting = false;
  }, 640);
}

function executeAnswerV2(plan) {
  clearScriptTimersV2();
  stateV2.currentPlan = plan;
  stateV2.currentAgentId = plan.agent.id;
  stateV2.activeScenarioId = plan.route?.id || "";
  stateV2.directAnswerMode = true;
  stateV2.pendingEntityPrompt = "";
  stateV2.currentFollowupSet = [...(plan.followups || [])];
  stateV2.autoActionQueue = [];
  hideListenOverlayV2();
  elsV2.mainInput.value = plan.text;
  applyToolStateV2(plan.toggles || []);
  highlightAgentV2(plan.agent.id);
  showBubbleV2({
    title: "我先直接回答你",
    copy: "",
    streamText: plan.answerPayload.summary,
    quickItems: buildQuickListV2(plan.followups),
    sticky: false
  });
  setPetStatusV2("这个问题我先直接回答，你还可以继续追问或让我展开页面");
  speakV2(plan.answerPayload.summary);
  if (plan.scriptId) runDemoScriptV2(plan.scriptId, plan);
}

function executeScriptedFlowV2(plan) {
  if (!plan || !plan.agent || stateV2.isExecuting) return;
  clearScriptTimersV2();
  if (plan.route.id === "script-answer-then-contract") {
    const answerAgent = getAgentV2("agent-zonghe");
    const answerPlan = {
      ...plan,
      agent: answerAgent,
      action: "answer_direct",
      toggles: ["knowledgeQA"],
      targetPage: answerAgent.destinationView,
      scriptId: null
    };
    const contractPlan = {
      ...plan,
      action: "open_workspace",
      targetPage: plan.agent.destinationView,
      chainPrelude: "海小南已先答复制度流程，再继续为你打开合同交底表。",
      scriptId: null
    };
    executeVisualV2(contractPlan, "我会先给你制度答复，再直接打开合同交底表，实现核心智能体串行调度。");
    setPetStatusV2("我会先把制度流程说明白，再替你打开合同交底表");
    stateV2.pendingModalPlan = contractPlan;
    openModalV2(answerPlan);
    runDemoScriptV2(plan.scriptId, answerPlan);
    speakV2(plan.answerPayload.summary);
    return;
  }
  if (plan.route.id === "script-budget-then-archive") {
    const metricPlan = {
      ...plan,
      agent: getAgentV2("agent-jicai"),
      action: "open_metric_page",
      targetPage: plan.metric.targetPage,
      toggles: ["deepThink", "webSearch"],
      scriptId: null
    };
    const archivePlan = {
      ...plan,
      metric: null,
      action: "open_workspace",
      targetPage: plan.agent.destinationView,
      scriptId: null
    };
    executeVisualV2(metricPlan, "我会先带你看本月预算完成率，再继续打开档案归档，核心智能体先判断再分发。");
    setPetStatusV2("我会先带你看预算指标，再继续落到档案归档页");
    stateV2.pendingModalPlan = archivePlan;
    openModalV2(metricPlan);
    runDemoScriptV2(plan.scriptId, metricPlan);
    speakV2(`${metricPlan.entities.period}的${metricPlan.metric.label}已经先帮你打开。`);
    return;
  }
  executeWorkspaceV2(plan);
}

function processCommandV2(text, source = "manual") {
  const commandText = String(text || "").trim();
  if (!commandText) return;
  const voiceDriven = source === "voice";
  if (!voiceDriven) elsV2.mainInput.value = commandText;
  setStateV2("thinking", voiceDriven ? 760 : 520);
  if (voiceDriven) updateVoicePresenceV2("voice", "thinking", commandText);
  else setPetStatusV2(`我听到你的需求是：${commandText}`);
  const route = resolveRouteV2(commandText);
  if (!route) {
    if (stateV2.currentPlan) {
      handleFollowV2(stateV2.currentPlan, commandText);
      return;
    }
    setStateV2("idle");
    showBubbleV2({
      title: "能再说具体一点吗",
      copy: "告诉我想处理什么业务、查什么数据，还是打开哪个页面，我来帮你调度。",
      quickItems: DEMO_COMMANDS_V2,
      sticky: false
    });
    return;
  }
  const plan = buildPlanV2(route, commandText, source);
  if (!plan) return;
  if (plan.action === "wake") {
    setStateV2("awake", 1600);
    setPetStatusV2("我在，你继续说业务需求就行");
    toastV2("海小南已唤醒", "success", "语音唤醒");
    return;
  }
  if (plan.action === "answer_direct") {
    executeAnswerV2(plan);
    return;
  }
  if (plan.action === "run_demo_script") {
    executeScriptedFlowV2(plan);
    return;
  }
  executeWorkspaceV2(plan);
}

function simulateCommandV2(phrase) {
  hideBubbleV2();
  showListenOverlayV2("正在为你处理", phrase);
  setStateV2("thinking");
  window.setTimeout(() => {
    hideListenOverlayV2();
    processCommandV2(phrase, "fallback");
  }, 620);
}

function queueVoiceCommandV2(text, source = "voice") {
  const content = String(text || "").trim();
  if (!content) return;
  updateVoicePresenceV2("voice", "thinking", content);
  window.setTimeout(() => processCommandV2(content, source), 260);
}

