function stopModalVoiceV2() {
  stateV2.modalVoiceBusy = false;
  if (stateV2.modalRecognition) {
    try {
      stateV2.modalRecognition.onend = null;
      stateV2.modalRecognition.onerror = null;
      stateV2.modalRecognition.onresult = null;
      stateV2.modalRecognition.stop();
    } catch (e) {}
    stateV2.modalRecognition = null;
  }
  const micBtn = document.getElementById("modal-follow-mic-v2");
  if (micBtn) micBtn.classList.remove("listening");
}

function startModalVoiceV2(plan, inputEl) {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) { toastV2("当前浏览器不支持语音识别", "warning", "语音追问"); return; }
  // 防并发：上一轮还在录或已有实例，先不重复启动
  if (stateV2.modalVoiceBusy || stateV2.modalRecognition) return;
  stateV2.modalVoiceBusy = true;
  const micBtn = document.getElementById("modal-follow-mic-v2");
  if (micBtn) micBtn.classList.add("listening");
  const rec = new SR();
  stateV2.modalRecognition = rec;
  rec.lang = "zh-CN";
  rec.continuous = false;
  rec.interimResults = true;
  rec.maxAlternatives = 1;
  let finalText = "";
  rec.onresult = (e) => {
    let interim = "";
    finalText = "";
    for (let i = 0; i < e.results.length; i++) {
      if (e.results[i].isFinal) finalText += e.results[i][0].transcript;
      else interim += e.results[i][0].transcript;
    }
    if (inputEl) inputEl.value = (finalText + interim).trim();
  };
  rec.onerror = (event) => {
    stateV2.modalVoiceBusy = false;
    stateV2.modalRecognition = null;
    if (micBtn) micBtn.classList.remove("listening");
    if (event && (event.error === "not-allowed" || event.error === "service-not-allowed")) {
      stateV2.modalVoiceLoop = false; // 权限被拒：停止自动续听，避免反复弹权限
      toastV2("麦克风权限被拒绝，可改用文字追问。", "warning", "语音追问");
      return;
    }
    // no-speech / aborted / network 等：温和重试，不打断对话
    if (stateV2.modalVoiceLoop) window.setTimeout(autoRelistenModalV2, 1200);
  };
  rec.onend = () => {
    stateV2.modalVoiceBusy = false;
    stateV2.modalRecognition = null;
    if (micBtn) micBtn.classList.remove("listening");
    const value = inputEl ? inputEl.value.trim() : "";
    if (value) {
      handleFollowV2(plan, value); // 回答完成后会在 onDone 里自动续听
      if (inputEl) inputEl.value = "";
    } else if (stateV2.modalVoiceLoop) {
      window.setTimeout(autoRelistenModalV2, 1200);
    }
  };
  try {
    rec.start();
  } catch (e) {
    stateV2.modalVoiceBusy = false;
    stateV2.modalRecognition = null;
    if (micBtn) micBtn.classList.remove("listening");
    if (stateV2.modalVoiceLoop) window.setTimeout(autoRelistenModalV2, 1200);
  }
}

function autoRelistenModalV2() {
  if (!stateV2.modalVoiceLoop || !stateV2.currentPlan) return;
  if (!elsV2.modalLayer.classList.contains("active")) return;
  if (stateV2.modalVoiceBusy || stateV2.modalRecognition) return; // 防并发
  const followInput = document.getElementById("modal-follow-input-v2");
  if (followInput) startModalVoiceV2(stateV2.currentPlan, followInput);
}

// 弹窗打开时暂停后台唤醒监听与主麦克风长听，避免与弹窗内语音抢麦
function suspendVoiceForModalV2() {
  if (stateV2.passiveEnabled) stateV2.passiveResumeAfterModal = true;
  stateV2.passiveEnabled = false;
  if (stateV2.passiveRecognition) {
    try {
      stateV2.passiveRecognition.onend = null;
      stateV2.passiveRecognition.onerror = null;
      stateV2.passiveRecognition.onresult = null;
      stateV2.passiveRecognition.stop();
    } catch (e) {}
    stateV2.passiveRecognition = null;
  }
  if (stateV2.standbyEnabled) {
    try { stopVoiceV2(true); } catch (e) {}
  }
}

// 弹窗关闭后恢复后台唤醒监听（主麦克风不自动恢复，避免突然又开始抢麦）

