.pet-face-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  transform: translate(var(--face-x, 0px), var(--face-y, 0px));
  transition: transform 0.18s ease-out;
}

.pet-eye {
  position: absolute;
  top: 49px;
  width: 28px;
  height: 18px;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(232, 238, 255, 0.65));
  transform: scaleY(0.08);
  transform-origin: center top;
  opacity: 0.95;
  mix-blend-mode: screen;
  box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.08);
}

.pet-eye-left {
  left: 23px;
  animation: petBlinkLeft 5.2s infinite ease-in-out;
}

.pet-eye-right {
  right: 23px;
  animation: petBlinkRight 5.2s infinite ease-in-out;
}

@keyframes petBlinkLeft {
  0%, 86%, 100% { transform: scaleY(0.08); }
  89%, 92% { transform: scaleY(0.95); }
  95% { transform: scaleY(0.2); }
}

