// 弹窗关闭后恢复后台唤醒监听（主麦克风不自动恢复，避免突然又开始抢麦）
function restoreVoiceAfterModalV2() {
  stateV2.passiveResumeAfterModal = false;
  // 只要已授权且当前没在监听，就恢复后台“小南小南”唤醒，保证问完一轮后语音还能继续
  if (!stateV2.voicePermissionGranted) return;
  window.setTimeout(() => {
    if (stateV2.passiveEnabled) return;
    if (elsV2.modalLayer.classList.contains("active")) return;
    autoPassiveListenV2();
  }, 500);
}

